You should project both geometries to the same coordinate system first:
```
import { SimpleDB } from "@nshiab/simple-data-analysis";
// We start a SimpleDB instance
const sdb = new SimpleDB();
// We create a new table
const table = sdb.newTable("geoTable");
// We load geospatial data from a file
await table.loadGeoData("./geodata.geojson");
// Project both geometries to the same coordinate system
await table.projectGeometry("geomA", "EPSG:4326");
await table.projectGeometry("geomB", "EPSG:4326");
// Now remove the intersection
await table.removeIntersection("geomA", "geomB", "geomResult");
// Log the results
await table.logTable();
// We close everything
await sdb.done();
```

